func buildDefinitionVersionThenLoader[Q orm.Loadable]() definitionVersionThenLoader[Q] {
	type StatsLoadInterface interface {
		LoadStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type DefinitionLoadInterface interface {
		LoadDefinition(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type MatchesLoadInterface interface {
		LoadMatches(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundsLoadInterface interface {
		LoadRounds(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return definitionVersionThenLoader[Q]{
		Stats: thenLoadBuilder[Q](
			"Stats",
			func(ctx context.Context, exec bob.Executor, retrieved StatsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStats(ctx, exec, mods...)
			},
		),
		Definition: thenLoadBuilder[Q](
			"Definition",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinition(ctx, exec, mods...)
			},
		),
		Matches: thenLoadBuilder[Q](
			"Matches",
			func(ctx context.Context, exec bob.Executor, retrieved MatchesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMatches(ctx, exec, mods...)
			},
		),
		Rounds: thenLoadBuilder[Q](
			"Rounds",
			func(ctx context.Context, exec bob.Executor, retrieved RoundsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRounds(ctx, exec, mods...)
			},
		),
	}
}

// LoadStats loads the definitionVersion's Stats into the .R struct
func (o *DefinitionVersion) LoadStats(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Stats = nil
	o.R.Loaded.Stats = false

	related, err := o.Stats(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.DefinitionVersions = DefinitionVersionSlice{o}
	}

	o.R.Stats = related
	o.R.Loaded.Stats = true
	return nil
}

// LoadStats loads the definitionVersion's Stats into the .R struct
func (os DefinitionVersionSlice) LoadStats(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	q := os.Stats(append(
		mods,
		// since we are changing the columns, the defaults must be added if the
		// original mods did not set any; this runs after the user mods and
		// before the related_* columns below, so it sees exactly what they set
		bob.ModFunc[*dialect.SelectQuery](func(q *dialect.SelectQuery) {
			if len(q.SelectList.Columns) == 0 {
				sm.Columns(Stats.Columns).Apply(q)
			}
		}),
		sm.Columns(DefinitionVersionStats.Columns.DefinitionVersionID.As("related_definition_versions.ID")),
	)...)

	IDSlice := make([]int64, 0, len(os))

	mapper := scan.Mod(q.Scanner, func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any, any) error) {
		// Resolve each joined key column name to its index once per query. The
		// previous code scanned by name on every row, which meant a linear column
		// search per row; the columns are added by this loader so they are always
		// present, but an unselected column simply stays unresolved and is skipped.
		IDIdx := -1
		for i, col := range cols {
			switch col {
			case "related_definition_versions.ID":
				IDIdx = i
			}
		}

		return func(row *scan.Row) (any, error) {
				IDSlice = append(IDSlice, *new(int64))
				if IDIdx >= 0 {
					row.ScheduleScanByIndex(IDIdx, &IDSlice[len(IDSlice)-1])
				}

				return nil, nil
			},
			func(any, any) error {
				return nil
			}
	})

	stats, err := bob.Allx[bob.SliceTransformer[*Stat, StatSlice]](ctx, exec, q, mapper)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}
		o.R.Stats = nil
		o.R.Loaded.Stats = true
	}
	// O(N+M) stitch via a map; child key is the carried slice IDSlice[i] (was O(N*M)).
	definitionVersionByKey := make(map[int64][]*DefinitionVersion, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		definitionVersionByKey[o.ID] = append(definitionVersionByKey[o.ID], o)
	}

	for i, rel := range stats {
		owners, ok := definitionVersionByKey[IDSlice[i]]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.DefinitionVersions = append(rel.R.DefinitionVersions, o)

			o.R.Stats = append(o.R.Stats, rel)

		}
	}

	return nil
}

// LoadDefinition loads the definitionVersion's Definition into the .R struct
func (o *DefinitionVersion) LoadDefinition(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Definition = nil
	o.R.Loaded.Definition = false

	related, err := o.Definition(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.DefinitionVersions = DefinitionVersionSlice{o}

	o.R.Definition = related
	o.R.Loaded.Definition = true
	return nil
}

// LoadDefinition loads the definitionVersion's Definition into the .R struct
func (os DefinitionVersionSlice) LoadDefinition(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitions, err := os.Definition(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Definition = nil
		o.R.Loaded.Definition = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	definitionVersionByKey := make(map[int64][]*DefinitionVersion, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		definitionVersionByKey[o.DefinitionID] = append(definitionVersionByKey[o.DefinitionID], o)
	}

	for _, rel := range definitions {

		owners, ok := definitionVersionByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Definition != nil {
				continue
			}

			rel.R.DefinitionVersions = append(rel.R.DefinitionVersions, o)

			o.R.Definition = rel

		}
	}

	return nil
}

