// definitionVersionC is where relationship counts are stored.
type definitionVersionC struct {
	Stats   *int64
	Matches *int64
	Rounds  *int64
}

// PreloadCount sets a count in the C struct by name
func (o *DefinitionVersion) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Stats":
		o.C.Stats = &count
	case "Matches":
		o.C.Matches = &count
	case "Rounds":
		o.C.Rounds = &count
	}
	return nil
}

type definitionVersionCountPreloader struct {
	Stats   func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Matches func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Rounds  func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildDefinitionVersionCountPreloader() definitionVersionCountPreloader {
	return definitionVersionCountPreloader{
		Stats: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*DefinitionVersion]("Stats", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = DefinitionVersions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(DefinitionVersionStats.NameAsExpr()),
					sm.Where(psql.Quote(DefinitionVersionStats.Alias(), "definition_version_id").EQ(psql.Quote(parent, "id"))),
					sm.InnerJoin(Stats.NameAsExpr()).On(
						psql.Quote(Stats.Alias(), "id").EQ(psql.Quote(DefinitionVersionStats.Alias(), "stat_id")),
					),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Matches: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*DefinitionVersion]("Matches", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = DefinitionVersions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Matches.NameAsExpr()),
					sm.Where(psql.Quote(Matches.Alias(), "definition_version_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Rounds: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*DefinitionVersion]("Rounds", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = DefinitionVersions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Rounds.NameAsExpr()),
					sm.Where(psql.Quote(Rounds.Alias(), "definition_version_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type definitionVersionCountThenLoader[Q orm.Loadable] struct {
	Stats   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Matches func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Rounds  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildDefinitionVersionCountThenLoader[Q orm.Loadable]() definitionVersionCountThenLoader[Q] {
	type StatsCountInterface interface {
		LoadCountStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type MatchesCountInterface interface {
		LoadCountMatches(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundsCountInterface interface {
		LoadCountRounds(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return definitionVersionCountThenLoader[Q]{
		Stats: countThenLoadBuilder[Q](
			"Stats",
			func(ctx context.Context, exec bob.Executor, retrieved StatsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStats(ctx, exec, mods...)
			},
		),
		Matches: countThenLoadBuilder[Q](
			"Matches",
			func(ctx context.Context, exec bob.Executor, retrieved MatchesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountMatches(ctx, exec, mods...)
			},
		),
		Rounds: countThenLoadBuilder[Q](
			"Rounds",
			func(ctx context.Context, exec bob.Executor, retrieved RoundsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountRounds(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountStats loads the count of Stats into the C struct
func (o *DefinitionVersion) LoadCountStats(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Stats(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Stats = &count
	return nil
}

// LoadCountStats loads the count of Stats for a slice in a single batch query
func (os DefinitionVersionSlice) LoadCountStats(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int64], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "bigint[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			DefinitionVersionStats.Columns.DefinitionVersionID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Multi-hop: FROM first join table, JOIN through to final related table
		sm.From(DefinitionVersionStats.NameAsExpr()),
		sm.InnerJoin(Stats.NameAsExpr()).On(
			Stats.Columns.ID.EQ(DefinitionVersionStats.Columns.StatID),
		),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(DefinitionVersionStats.Columns.DefinitionVersionID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(DefinitionVersionStats.Columns.DefinitionVersionID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Stats = &count
	}

	return nil
}

