type definitionVersionJoins[Q dialect.Joinable] struct {
	typ        string
	Stats      modAs[Q, statColumns]
	Definition modAs[Q, definitionColumns]
	Matches    modAs[Q, matchColumns]
	Rounds     modAs[Q, roundColumns]
}

func (j definitionVersionJoins[Q]) aliasedAs(alias string) definitionVersionJoins[Q] {
	return buildDefinitionVersionJoins[Q](buildDefinitionVersionColumns(alias), j.typ)
}

func buildDefinitionVersionJoins[Q dialect.Joinable](cols definitionVersionColumns, typ string) definitionVersionJoins[Q] {
	return definitionVersionJoins[Q]{
		typ: typ,
		Stats: modAs[Q, statColumns]{
			c: Stats.Columns,
			f: func(to statColumns) bob.Mod[Q] {
				uniqueSuffix := strconv.FormatUint(bob.NextUniqueInt(), 10)
				mods := make(mods.QueryMods[Q], 0, 2)

				{
					to := DefinitionVersionStats.Columns.AliasedAs(DefinitionVersionStats.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, DefinitionVersionStats.NameExpr().As(to.Alias())).On(
						to.DefinitionVersionID.EQ(cols.ID),
					))
				}
				{
					cols := DefinitionVersionStats.Columns.AliasedAs(DefinitionVersionStats.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, Stats.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.StatID),
					))
				}

				return mods
			},
		},
		Definition: modAs[Q, definitionColumns]{
			c: Definitions.Columns,
			f: func(to definitionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Definitions.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.DefinitionID),
					))
				}

				return mods
			},
		},
		Matches: modAs[Q, matchColumns]{
			c: Matches.Columns,
			f: func(to matchColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Matches.NameExpr().As(to.Alias())).On(
						to.DefinitionVersionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Rounds: modAs[Q, roundColumns]{
			c: Rounds.Columns,
			f: func(to roundColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Rounds.NameExpr().As(to.Alias())).On(
						to.DefinitionVersionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
